import{_ as i,o as e,c as a,a2 as t}from"./chunks/framework.BXA5Pi9t.js";const p=JSON.parse('{"title":"2019-04-25 :: Ceph Code Walkthrough: RGW Request Workflow","description":"","frontmatter":{"title":"2019-04-25 :: Ceph Code Walkthrough: RGW Request Workflow","date":"2019-04-25T00:00:00.000Z","updated":"2019-04-25T00:00:00.000Z","tags":["Ceph","RGW","Request Workflow","Object Storage","CephFS"],"categories":["视频总结"],"outline":"deep"},"headers":[],"relativePath":"posts/2019/2019-04-25_-_-_Ceph_Code_Walkthrough_-_RGW_Request_Workflow.md","filePath":"posts/2019/2019-04-25_-_-_Ceph_Code_Walkthrough_-_RGW_Request_Workflow.md","lastUpdated":1780459816000}'),o={name:"posts/2019/2019-04-25_-_-_Ceph_Code_Walkthrough_-_RGW_Request_Workflow.md"};function r(s,l,h,n,u,d){return e(),a("div",null,[...l[0]||(l[0]=[t('<h3 id="会议纪要" tabindex="-1">会议纪要 <a class="header-anchor" href="#会议纪要" aria-label="Permalink to &quot;会议纪要&quot;">​</a></h3><h4 id="会议主题-ceph-rgw子系统及请求工作流程介绍" tabindex="-1">会议主题：Ceph RGW子系统及请求工作流程介绍 <a class="header-anchor" href="#会议主题-ceph-rgw子系统及请求工作流程介绍" aria-label="Permalink to &quot;会议主题：Ceph RGW子系统及请求工作流程介绍&quot;">​</a></h4><h4 id="会议时间-具体时间" tabindex="-1">会议时间：[具体时间] <a class="header-anchor" href="#会议时间-具体时间" aria-label="Permalink to &quot;会议时间：[具体时间]&quot;">​</a></h4><h4 id="会议地点-具体地点" tabindex="-1">会议地点：[具体地点] <a class="header-anchor" href="#会议地点-具体地点" aria-label="Permalink to &quot;会议地点：[具体地点]&quot;">​</a></h4><h4 id="参会人员-参会人员名单" tabindex="-1">参会人员：[参会人员名单] <a class="header-anchor" href="#参会人员-参会人员名单" aria-label="Permalink to &quot;参会人员：[参会人员名单]&quot;">​</a></h4><h4 id="会议内容" tabindex="-1">会议内容： <a class="header-anchor" href="#会议内容" aria-label="Permalink to &quot;会议内容：&quot;">​</a></h4><ol><li><p><strong>介绍与目的</strong></p><ul><li>本次会议旨在为新RGW开发者介绍RGW子系统及其请求工作流程。</li><li>会议内容基于上一次RGW介绍，深入探讨RGW的特性和子组件。</li><li>会议面向新RGW开发者，为其打下基础，并为未来的深入讨论做准备。</li></ul></li><li><p><strong>RGW概述</strong></p><ul><li>RGW作为Ceph的对象网关，处理客户端通过HTTP与S3和Swift协议的交互。</li><li>RGW通过librados与OSD通信，管理用户和凭证，处理对象存储操作。</li><li>RGW包含多个子系统，如前端服务器、认证引擎、操作处理等。</li></ul></li><li><p><strong>RGW子系统详细介绍</strong></p><ul><li><strong>前端服务器</strong>：包括CivetWeb和Beast，分别基于C和C++实现，处理HTTP请求。</li><li><strong>认证引擎</strong>：支持本地用户认证和外部认证（如Keystone、STS、LDAP）。</li><li><strong>操作处理</strong>：包括S3和Swift协议的具体操作，如创建桶、上传下载对象等。</li><li><strong>对象布局</strong>：介绍如何在Rados中映射S3和Swift的桶和对象概念。</li><li><strong>多站点复制</strong>：通过多集群实现数据复制，避免Paxos在广域网中的不稳定性。</li><li><strong>垃圾收集与生命周期管理</strong>：后台删除对象，管理桶的生命周期规则。</li><li><strong>RGW Admin与NFS插件</strong>：提供管理工具和NFS Ganesha插件。</li></ul></li><li><p><strong>请求工作流程</strong></p><ul><li>客户端发送请求至RGW前端。</li><li>前端调用<code>process_request</code>函数，触发认证引擎和操作处理。</li><li>认证通过后，执行具体操作，如读写对象。</li><li>操作完成后，返回响应给客户端。</li></ul></li><li><p><strong>后续行动计划</strong></p><ul><li>未来会议将深入探讨RGW的各个子组件，包括代码走查和实际操作演示。</li><li>鼓励参会者提供反馈，希望了解他们对未来会议内容的具体需求。</li></ul></li></ol><h4 id="会议记录" tabindex="-1">会议记录： <a class="header-anchor" href="#会议记录" aria-label="Permalink to &quot;会议记录：&quot;">​</a></h4><ul><li>会议全程录制，链接将在稍后提供。</li><li>鼓励参会者在会议结束后提出问题。</li></ul><h4 id="会议结束语" tabindex="-1">会议结束语： <a class="header-anchor" href="#会议结束语" aria-label="Permalink to &quot;会议结束语：&quot;">​</a></h4><ul><li>感谢所有参会者的参与和支持。</li><li>期待在未来的会议中再次与大家见面。</li></ul><h4 id="会议组织者" tabindex="-1">会议组织者： <a class="header-anchor" href="#会议组织者" aria-label="Permalink to &quot;会议组织者：&quot;">​</a></h4><ul><li>[组织者姓名]</li></ul><h4 id="会议记录人" tabindex="-1">会议记录人： <a class="header-anchor" href="#会议记录人" aria-label="Permalink to &quot;会议记录人：&quot;">​</a></h4><ul><li>[记录人姓名]</li></ul><p>在原始总结中，以下要点被准确反映：</p><ul><li>会议的主题和目的</li><li>RGW的关键特性和子组件</li><li>RGW子系统的工作流程</li><li>请求工作流程的详细说明</li><li>后续行动计划</li></ul><p>改进后的总结中，保留了以下Ceph相关关键字：</p><ul><li>Ceph</li><li>RGW</li><li>request workflow</li><li>object storage</li><li>cephfs</li><li>librados</li><li>authentication</li><li>authorization</li><li>swift</li><li>s3</li><li>paxos</li><li>garbage collection</li><li>lifecycle management</li><li>rgw admin</li><li>nfs plugin</li></ul><p>标签反映了文章的主要主题和技术焦点：</p><ul><li>[Ceph]</li><li>[RGW]</li><li>[Request Workflow]</li><li>[Object Storage]</li><li>[CephFS]</li></ul>',21)])])}const c=i(o,[["render",r]]);export{p as __pageData,c as default};
